import numpy as np, json, os

factors = ['down_beta_60','cn10y_beta_60','spx_beta_60','vol_adj_mom_20_60','dxy_beta_cond_60x20','hs300_beta_60','intraday_ret_skew_20','vol_of_vol20x60','dd_duration_120_resid','mom_accel_60_120','hilo_pos_60']
sig = {}
for f in factors:
    p = f'factors/{f}_signal.npy'
    if os.path.exists(p):
        sig[f] = np.load(p)
    else:
        try:
            d = json.load(open(f'factors/{f}.json'))
            sa = d.get('signal_artifact')
            if isinstance(sa, dict) and 'data' in sa:
                sig[f] = np.array(sa['data'])
        except Exception as e:
            print(f, 'ERR', e)

names = list(sig.keys())
n = len(names)
W = 120
print('Pairwise cross-sectional corr (mean over last', W, 'dates, tail-aligned):')
mat = np.full((n,n), np.nan)
for i in range(n):
    for j in range(i+1,n):
        a = sig[names[i]][-W:]; b = sig[names[j]][-W:]
        T = min(a.shape[0], b.shape[0])
        a = a[-T:]; b = b[-T:]
        cs = []
        for t in range(T):
            m = np.isfinite(a[t]) & np.isfinite(b[t])
            if m.sum() >= 8:
                c = np.corrcoef(a[t][m], b[t][m])[0,1]
                if np.isfinite(c): cs.append(c)
        mat[i,j] = mat[j,i] = np.mean(cs) if cs else np.nan

print('        ' + ' '.join(f'{t[:8]:>9s}' for t in names))
for i in range(n):
    print(f'{names[i][:8]:>8s} ' + ' '.join(f'{mat[i,j]:9.2f}' if np.isfinite(mat[i,j]) else '      nan' for j in range(n)))

print()
print('Pairs with |rho| > 0.7:')
for i in range(n):
    for j in range(i+1,n):
        if np.isfinite(mat[i,j]) and abs(mat[i,j]) > 0.7:
            print(f'  {names[i]} ~ {names[j]}: rho={mat[i,j]:.3f}')
print()
print('Max pairwise |rho| for selected top-10 candidates (among available):')
sel = ['down_beta_60','cn10y_beta_60','spx_beta_60','vol_adj_mom_20_60','dxy_beta_cond_60x20','hs300_beta_60','intraday_ret_skew_20','vol_of_vol20x60','dd_duration_120_resid']
for f in sel:
    if f in sig:
        i = names.index(f)
        rhos = [abs(mat[i,j]) for j in range(n) if j!=i and np.isfinite(mat[i,j])]
        print(f'  {f}: max_rho={max(rhos):.3f}')
"

