import json, glob
# Inspect metadata structure to locate IC / ICIR fields and verify direction == sign(IC)
for p in sorted(glob.glob('factors/*.json')):
    if p.endswith('.bak') or 'factor_ensemble' in p:
        continue
    meta = json.load(open(p))
    fid = meta.get('factor_id', p.split('/')[-1][:-5])
    # find ic-like keys
    def find_ic(d, path=""):
        out = []
        if isinstance(d, dict):
            for k, v in d.items():
                if 'ic' in k.lower() and not isinstance(v, (dict, list)):
                    out.append((path + k, v))
                else:
                    out += find_ic(v, path + k + ".")
        return out
    ics = find_ic(meta)
    # print only primary ic fields
    prim = [(k, round(v,4)) for k, v in ics if k.endswith('ic') or 'icir' in k][:3]
    print(f"{fid:26s} {prim}")
